import { ConfigService } from '@nestjs/config';
import {
  TreasuryConsumer,
  MessageCommitter,
} from '../../src/treasury/consumer/treasury.consumer';
import {
  CapacityEventHandler,
  InboundMessage,
} from '../../src/treasury/handlers/capacity-event.handler';
import { ReconciliationSnapshotHandler } from '../../src/treasury/handlers/reconciliation-snapshot.handler';
import { DlqPublisher, DlqRecord } from '../../src/treasury/dlq/dlq.publisher';
import { RetryPolicy } from '../../src/treasury/retry/failure-classifier';
import {
  getConsumerStatus,
  resetConsumerStatus,
} from '../../src/shared/health/consumer-health';

type CrashListener = (event: { payload: unknown }) => void;

interface KafkaMockConsumer {
  connect: jest.Mock;
  subscribe: jest.Mock;
  run: jest.Mock;
  commitOffsets: jest.Mock;
  disconnect: jest.Mock;
  on: jest.Mock;
  events: {
    CRASH: string;
    DISCONNECT: string;
    GROUP_JOIN: string;
    HEARTBEAT: string;
    REQUEST_TIMEOUT: string;
  };
  __emit: (name: string, payload: unknown) => void;
  __listeners: Record<string, CrashListener[]>;
}

jest.mock('kafkajs', () => {
  const listeners: Record<string, CrashListener[]> = {};
  const emit = (name: string, payload: unknown): void => {
    for (const listener of listeners[name] ?? []) {
      listener({ payload });
    }
  };
  const consumer = {
    connect: jest.fn().mockResolvedValue(undefined),
    subscribe: jest.fn().mockResolvedValue(undefined),
    run: jest.fn().mockResolvedValue(undefined),
    commitOffsets: jest.fn().mockResolvedValue(undefined),
    on: jest.fn((name: string, listener: CrashListener) => {
      (listeners[name] ??= []).push(listener);
    }),
    disconnect: jest.fn().mockResolvedValue(undefined),
    events: {
      CRASH: 'consumer.crash',
      DISCONNECT: 'consumer.disconnect',
      GROUP_JOIN: 'consumer.group_join',
      HEARTBEAT: 'consumer.heartbeat',
      REQUEST_TIMEOUT: 'consumer.request_timeout',
    },
    __emit: emit,
    __listeners: listeners,
  };
  return {
    Kafka: jest.fn(function () {
      return { consumer: () => consumer };
    }),
    PartitionAssigners: { roundRobin: () => ({}) },
    CompressionCodecs: {},
    CompressionTypes: { Snappy: 2 },
    __consumer: consumer,
  };
});

const kafkajsMock = jest.requireMock('kafkajs') as {
  Kafka: jest.Mock;
  __consumer: KafkaMockConsumer;
};

const RETRY: RetryPolicy = { maxAttempts: 2, baseDelayMs: 1, maxDelayMs: 1 };

const DEV_CONFIG = {
  NODE_ENV: 'development',
  KAFKA_BROKERS: 'broker:9093',
  KAFKA_SASL_USERNAME: 'capacity',
  KAFKA_SASL_PASSWORD: 'secret',
  KAFKA_CONSUMER_GROUP_ID: 'capacity-treasury-consumer',
  KAFKA_CAPACITY_EVENTS_TOPIC: 'treasury.capacity.events',
  KAFKA_DLQ_TOPIC: 'treasury.capacity.dlq',
} as const;

function config(values: Record<string, unknown>): ConfigService {
  return {
    get: (key: string, fallback?: unknown) => values[key] ?? fallback,
    getOrThrow: (key: string) => {
      if (!(key in values)) {
        throw new Error(`missing ${key}`);
      }
      return values[key];
    },
  } as unknown as ConfigService;
}

class RecordingDlq implements DlqPublisher {
  readonly records: DlqRecord[] = [];
  async publish(record: DlqRecord): Promise<void> {
    this.records.push(record);
  }
}

function fixedHandler(outcome: unknown): CapacityEventHandler {
  return { handle: async () => outcome } as unknown as CapacityEventHandler;
}

function throwingHandler(error: Error): CapacityEventHandler {
  return {
    handle: async () => {
      throw error;
    },
  } as unknown as CapacityEventHandler;
}

function committer(): MessageCommitter & { committed: string[] } {
  const committed: string[] = [];
  return {
    committed,
    commitOffset: async (m: InboundMessage) => {
      committed.push(m.offset);
    },
  };
}

// The consumer routes by topic; these tests exercise the event path, so the
// snapshot handler is a stub that is never reached.
const NOOP_SNAPSHOTS = {
  handle: async () => ({ kind: 'applied' }),
} as unknown as ReconciliationSnapshotHandler;

function makeConsumer(
  handler: CapacityEventHandler,
  dlq: DlqPublisher,
  retryPolicy: RetryPolicy,
  cfg: ConfigService,
): TreasuryConsumer {
  return new TreasuryConsumer(
    handler,
    NOOP_SNAPSHOTS,
    dlq,
    retryPolicy,
    cfg,
  );
}

const flush = async (): Promise<void> => {
  await new Promise((resolve) => setImmediate(resolve));
  await new Promise((resolve) => setImmediate(resolve));
};

const tick = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

describe('TreasuryConsumer (Kafka wiring)', () => {
  beforeEach(() => {
    kafkajsMock.Kafka.mockClear();
    kafkajsMock.__consumer.connect.mockClear().mockResolvedValue(undefined);
    kafkajsMock.__consumer.subscribe.mockClear().mockResolvedValue(undefined);
    kafkajsMock.__consumer.commitOffsets
      .mockClear()
      .mockResolvedValue(undefined);
    kafkajsMock.__consumer.disconnect.mockClear().mockResolvedValue(undefined);
    kafkajsMock.__consumer.on.mockClear();
    kafkajsMock.__consumer.run.mockClear().mockResolvedValue(undefined);
    for (const key of Object.keys(kafkajsMock.__consumer.__listeners)) {
      delete kafkajsMock.__consumer.__listeners[key];
    }
    resetConsumerStatus();
  });

  it('does not start the broker connection under NODE_ENV=test', async () => {
    const consumer = makeConsumer(
      fixedHandler({ kind: 'applied' }),
      new RecordingDlq(),
      RETRY,
      config({ NODE_ENV: 'test' }),
    );

    await consumer.onModuleInit();
    await flush();

    expect(kafkajsMock.Kafka).not.toHaveBeenCalled();
    await consumer.onModuleDestroy();
    expect(kafkajsMock.__consumer.disconnect).not.toHaveBeenCalled();
  });

  it('connects, subscribes, runs with autoCommit disabled, and commits offset+1', async () => {
    const consumer = makeConsumer(
      fixedHandler({ kind: 'applied' }),
      new RecordingDlq(),
      RETRY,
      config(DEV_CONFIG),
    );

    await consumer.onModuleInit();
    await flush();

    const kafkaConsumer = kafkajsMock.__consumer;
    expect(kafkaConsumer.connect).toHaveBeenCalledTimes(1);
    expect(kafkaConsumer.subscribe).toHaveBeenCalledWith({
      topics: [
        'treasury.capacity.events',
        'treasury.capacity.snapshots',
      ],
      fromBeginning: false,
    });
    expect(kafkaConsumer.on).toHaveBeenCalledWith(
      'consumer.crash',
      expect.any(Function),
    );
    expect(getConsumerStatus()).toBe('up');

    const runArgs = kafkaConsumer.run.mock.calls[0]?.[0] as {
      autoCommit: boolean;
      eachMessage: (input: unknown) => Promise<void>;
    };
    expect(runArgs.autoCommit).toBe(false);

    await runArgs.eachMessage({
      topic: 'treasury.capacity.events',
      partition: 0,
      message: {
        offset: '4',
        key: null,
        value: Buffer.from('{}'),
        headers: { correlationId: ['first', 'second'] },
      },
      heartbeat: () => undefined,
      pause: () => undefined,
    });

    expect(kafkaConsumer.commitOffsets).toHaveBeenCalledWith([
      { topic: 'treasury.capacity.events', partition: 0, offset: '5' },
    ]);

    await consumer.onModuleDestroy();
    expect(getConsumerStatus()).toBe('down');
  });

  it('rebuilds the consumer after a non-retriable crash and republishes readiness up', async () => {
    const consumer = makeConsumer(
      fixedHandler({ kind: 'applied' }),
      new RecordingDlq(),
      RETRY,
      config(DEV_CONFIG),
    );

    await consumer.onModuleInit();
    await flush();
    expect(kafkajsMock.Kafka).toHaveBeenCalledTimes(1);

    kafkajsMock.__consumer.__emit('consumer.crash', {
      error: new Error('KafkaJSNotImplemented: Snappy compression not implemented'),
      groupId: 'capacity-treasury-consumer',
      restart: false,
    });
    expect(getConsumerStatus()).toBe('down');
    await tick(30);

    expect(kafkajsMock.Kafka).toHaveBeenCalledTimes(2);
    expect(kafkajsMock.__consumer.connect).toHaveBeenCalledTimes(2);
    expect(getConsumerStatus()).toBe('up');

    await consumer.onModuleDestroy();
    expect(getConsumerStatus()).toBe('down');
  });

  it('leaves a retriable crash to KafkaJS and does not rebuild', async () => {
    const consumer = makeConsumer(
      fixedHandler({ kind: 'applied' }),
      new RecordingDlq(),
      RETRY,
      config(DEV_CONFIG),
    );

    await consumer.onModuleInit();
    await flush();

    kafkajsMock.__consumer.__emit('consumer.crash', {
      error: new Error('temporary'),
      groupId: 'capacity-treasury-consumer',
      restart: true,
    });
    await tick(30);

    expect(kafkajsMock.Kafka).toHaveBeenCalledTimes(1);
    // KafkaJS restarts this one internally; readiness must still show it is
    // down until the group re-joins.
    expect(getConsumerStatus()).toBe('down');

    kafkajsMock.__consumer.__emit('consumer.group_join', {
      groupId: 'capacity-treasury-consumer',
    });
    expect(getConsumerStatus()).toBe('up');

    await consumer.onModuleDestroy();
  });

  it('drops readiness when a request stalls and restores it on the next heartbeat', async () => {
    const consumer = makeConsumer(
      fixedHandler({ kind: 'applied' }),
      new RecordingDlq(),
      RETRY,
      config(DEV_CONFIG),
    );

    await consumer.onModuleInit();
    await flush();
    expect(getConsumerStatus()).toBe('up');

    // A paused broker stalls the heartbeat past the KafkaJS request timeout,
    // which surfaces as REQUEST_TIMEOUT rather than a crash (KafkaJS retries
    // internally). Readiness must reflect that the consumer cannot ingest.
    kafkajsMock.__consumer.__emit('consumer.request_timeout', {
      duration: 30000,
    });
    expect(getConsumerStatus()).toBe('down');

    // Once the broker responds again the next heartbeat proves liveness.
    kafkajsMock.__consumer.__emit('consumer.heartbeat', {
      groupId: 'capacity-treasury-consumer',
    });
    expect(getConsumerStatus()).toBe('up');

    await consumer.onModuleDestroy();
  });
});

describe('TreasuryConsumer.processMessage correlation ids', () => {
  beforeEach(() => {
    resetConsumerStatus();
  });

  it('routes a snapshot-topic message to the snapshot handler, not the event handler', async () => {
    const eventHandler = { handle: jest.fn().mockResolvedValue({ kind: 'applied' }) };
    const snapshotHandler = {
      handle: jest.fn().mockResolvedValue({ kind: 'applied' }),
    };
    const consumer = new TreasuryConsumer(
      eventHandler as unknown as CapacityEventHandler,
      snapshotHandler as unknown as ReconciliationSnapshotHandler,
      new RecordingDlq(),
      RETRY,
      config({
        NODE_ENV: 'test',
        KAFKA_CAPACITY_EVENTS_TOPIC: 'treasury.capacity.events',
        KAFKA_SNAPSHOTS_TOPIC: 'treasury.capacity.snapshots',
      }),
    );
    const c = committer();

    await consumer.processMessage(
      {
        topic: 'treasury.capacity.snapshots',
        partition: 0,
        offset: '7',
        key: null,
        value: Buffer.from('{}'),
        headers: {},
      },
      c,
    );

    expect(snapshotHandler.handle).toHaveBeenCalledTimes(1);
    expect(eventHandler.handle).not.toHaveBeenCalled();
    expect(c.committed).toEqual(['7']);
  });

  it('passes a string correlation id through and quarantines the message', async () => {
    const dlq = new RecordingDlq();
    const consumer = makeConsumer(
      fixedHandler({ kind: 'quarantined', reason: 'SCHEMA_INVALID' }),
      dlq,
      RETRY,
      config({ NODE_ENV: 'test' }),
    );
    const c = committer();

    await consumer.processMessage(
      {
        topic: 'treasury.capacity.events',
        partition: 0,
        offset: '1',
        key: null,
        value: Buffer.from('{}'),
        headers: { correlationId: 'corr-1' },
      },
      c,
    );

    expect(dlq.records[0]?.correlationId).toBe('corr-1');
    expect(c.committed).toEqual(['1']);
  });

  it('decodes a buffer correlation id and treats a missing one as null', async () => {
    const dlq = new RecordingDlq();
    const consumer = makeConsumer(
      fixedHandler({ kind: 'quarantined', reason: 'UNKNOWN_PROGRAM' }),
      dlq,
      RETRY,
      config({ NODE_ENV: 'test' }),
    );

    await consumer.processMessage(
      {
        topic: 't',
        partition: 0,
        offset: '1',
        key: null,
        value: null,
        headers: { correlationId: Buffer.from('from-buffer') },
      },
      committer(),
    );
    await consumer.processMessage(
      { topic: 't', partition: 0, offset: '2', key: null, value: null, headers: {} },
      committer(),
    );

    expect(dlq.records[0]?.correlationId).toBe('from-buffer');
    expect(dlq.records[1]?.correlationId).toBeNull();
  });

  it('rethrows a code-less transient failure without DLQ publish or offset commit (FR-035)', async () => {
    const dlq = new RecordingDlq();
    const consumer = makeConsumer(
      // pg-pool's connect timeout is a plain Error with no `code`.
      throwingHandler(new Error('timeout exceeded when trying to connect')),
      dlq,
      RETRY,
      config({ NODE_ENV: 'test' }),
    );
    const c = committer();

    await expect(
      consumer.processMessage(
        { topic: 't', partition: 0, offset: '1', key: null, value: null, headers: {} },
        c,
      ),
    ).rejects.toThrow();

    expect(dlq.records).toHaveLength(0);
    expect(c.committed).toHaveLength(0);
  });

  it('quarantines an unrecognised (non-transient) handler failure and commits its offset', async () => {
    const dlq = new RecordingDlq();
    const consumer = makeConsumer(
      throwingHandler(new Error('boom')),
      dlq,
      RETRY,
      config({ NODE_ENV: 'test' }),
    );
    const c = committer();

    await consumer.processMessage(
      { topic: 't', partition: 0, offset: '1', key: null, value: null, headers: {} },
      c,
    );

    expect(dlq.records[0]?.reason).toBe('HANDLER_FAILURE');
    expect(c.committed).toEqual(['1']);
  });
});

test/unit/release-policy.spec.ts.source:
import {
  ReleaseInput,
  ReservationSnapshot,
  releasePolicy,
} from '../../src/capacity/domain/policies/release.policy';
import { money } from '../../src/shared/money/money';
import {
  RATE_SCALE,
  convert,
  roundHalfUp,
  scaleRate,
} from '../../src/shared/money/convert';

function snapshot(
  overrides: Partial<ReservationSnapshot> = {},
): ReservationSnapshot {
  return {
    invoiceCurrency: 'USD',
    programCurrency: 'USD',
    outstandingInvoiceMinor: 1_000n,
    outstandingReservedMinor: 1_000n,
    status: 'ACTIVE',
    ...overrides,
  };
}

function release(overrides: Partial<ReleaseInput> = {}): ReleaseInput {
  return {
    releaseMinor: 100n,
    releaseCurrency: 'USD',
    reservation: snapshot(),
    scaledRate: scaleRate('1.0'),
    ...overrides,
  };
}

describe('releasePolicy', () => {
  it('snaps a full repayment to the reserved remainder even when the conversion rounds off by one', () => {
    const decision = releasePolicy(
      release({
        releaseMinor: 100n,
        reservation: snapshot({
          outstandingInvoiceMinor: 100n,
          outstandingReservedMinor: 110n,
        }),
        // round_half_up(100 * 1.085) === 109, one unit below the reserved remainder.
        scaledRate: scaleRate('1.0850000000'),
      }),
    );

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor).toBe(110n);
      expect(decision.value.outstandingInvoiceMinor).toBe(0n);
      expect(decision.value.outstandingReservedMinor).toBe(0n);
      expect(decision.value.status).toBe('FULLY_RELEASED');
    }
  });

  it('refuses a release larger than the outstanding invoice instead of driving it negative', () => {
    // At a sub-1 rate 101 units convert to 10, within the reserved remainder of
    // 10; without the invoice bound this would leave outstanding_invoice at -1.
    const decision = releasePolicy(
      release({
        releaseMinor: 101n,
        reservation: snapshot({
          outstandingInvoiceMinor: 100n,
          outstandingReservedMinor: 10n,
        }),
        scaledRate: scaleRate('0.1000000000'),
      }),
    );

    expect(decision.ok).toBe(false);
    if (!decision.ok) {
      expect(decision.error).toBe('RELEASE_EXCEEDS_RESERVED');
    }
  });

  it('refuses an inconsistent reservation whose reserved is below its converted invoice', () => {
    // Exercises the `deltaMinor < 0n` branch at release.policy.ts:107-109.
    const decision = releasePolicy(
      release({
        releaseMinor: 101n,
        reservation: snapshot({
          outstandingInvoiceMinor: 1_000n,
          outstandingReservedMinor: 100n,
        }),
      }),
    );

    expect(decision.ok).toBe(false);
    if (!decision.ok) {
      expect(decision.error).toBe('RELEASE_EXCEEDS_RESERVED');
    }
  });

  it('refuses a release larger than the outstanding invoice', () => {
    // Exercises the invoice-currency bound at release.policy.ts:70-72.
    const rate = scaleRate('1.0');
    const decision = releasePolicy(
      release({
        releaseMinor: 1_001n,
        reservation: snapshot({
          outstandingInvoiceMinor: 1_000n,
          outstandingReservedMinor: roundHalfUp(1_000n * rate, RATE_SCALE),
        }),
        scaledRate: rate,
      }),
    );

    expect(decision.ok).toBe(false);
    if (!decision.ok) {
      expect(decision.error).toBe('RELEASE_EXCEEDS_RESERVED');
    }
  });

  it('keeps outstandingReserved equal to the converted outstanding invoice after a partial release', () => {
    const rate = scaleRate('0.9216589862');
    const decision = releasePolicy(
      release({
        releaseMinor: 400n,
        reservation: snapshot({
          programCurrency: 'EUR',
          outstandingInvoiceMinor: 1_000n,
          outstandingReservedMinor: roundHalfUp(1_000n * rate, RATE_SCALE),
        }),
        scaledRate: rate,
      }),
    );

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.outstandingInvoiceMinor).toBe(600n);
      const remainder = convert(money(600n, 'EUR'), 'EUR', rate);
      expect(remainder.kind).toBe('converted');
      if (remainder.kind === 'converted') {
        expect(decision.value.outstandingReservedMinor).toBe(
          remainder.amount.minor,
        );
      }
    }
  });

  it('refuses a release whose converted value rounds to zero', () => {
    const decision = releasePolicy(
      release({
        releaseMinor: 1n,
        reservation: snapshot({
          outstandingInvoiceMinor: 5n,
          outstandingReservedMinor: 1n,
        }),
        scaledRate: scaleRate('0.2000000000'),
      }),
    );

    expect(decision.ok).toBe(false);
    if (!decision.ok) {
      expect(decision.error).toBe('AMOUNT_ROUNDS_TO_ZERO');
    }
  });

  it('refuses a release that would return no capacity even when the invoice shrinks', () => {
    const decision = releasePolicy(
      release({
        releaseMinor: 1n,
        reservation: snapshot({
          outstandingInvoiceMinor: 2n,
          outstandingReservedMinor: 1n,
        }),
        scaledRate: scaleRate('0.5000000000'),
      }),
    );

    expect(decision.ok).toBe(false);
    if (!decision.ok) {
      expect(decision.error).toBe('AMOUNT_ROUNDS_TO_ZERO');
    }
  });

  it('settles a remainder worth less than one minor unit as sub-unit dust', () => {
    const decision = releasePolicy(
      release({
        releaseMinor: 4n,
        reservation: snapshot({
          outstandingInvoiceMinor: 5n,
          outstandingReservedMinor: 1n,
        }),
        scaledRate: scaleRate('0.2000000000'),
      }),
    );

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor).toBe(1n);
      expect(decision.value.outstandingInvoiceMinor).toBe(0n);
      expect(decision.value.outstandingReservedMinor).toBe(0n);
      expect(decision.value.status).toBe('FULLY_RELEASED');
    }
  });

  it('decreases both outstandings by their respective amounts on a partial release', () => {
    const decision = releasePolicy(
      release({
        releaseMinor: 100n,
        reservation: snapshot({
          outstandingInvoiceMinor: 1_000n,
          outstandingReservedMinor: 250n,
        }),
        scaledRate: scaleRate('0.25'),
      }),
    );

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor).toBe(25n);
      expect(decision.value.outstandingInvoiceMinor).toBe(900n);
      expect(decision.value.outstandingReservedMinor).toBe(225n);
      expect(decision.value.status).toBe('PARTIALLY_RELEASED');
    }
  });

  it('converts the release at the rate fixed on the reservation', () => {
    const decision = releasePolicy(
      release({
        releaseMinor: 20_000n,
        releaseCurrency: 'EUR',
        reservation: snapshot({
          invoiceCurrency: 'EUR',
          programCurrency: 'USD',
          outstandingInvoiceMinor: 33_333n,
          outstandingReservedMinor: 36_166n,
        }),
        scaledRate: scaleRate('1.0850000000'),
      }),
    );

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor).toBe(21_700n);
      expect(decision.value.outstandingInvoiceMinor).toBe(13_333n);
      expect(decision.value.outstandingReservedMinor).toBe(14_466n);
      expect(decision.value.status).toBe('PARTIALLY_RELEASED');
    }
  });

  it('does not strand a sub-1-rate reservation short of FULLY_RELEASED', () => {
    const scaledRate = scaleRate('0.9200000000');

    const first = releasePolicy(
      release({
        releaseMinor: 40n,
        reservation: snapshot({
          programCurrency: 'EUR',
          outstandingInvoiceMinor: 100n,
          outstandingReservedMinor: 92n,
        }),
        scaledRate,
      }),
    );

    expect(first.ok).toBe(true);
    if (!first.ok) {
      return;
    }
    expect(first.value.deltaMinor).toBe(37n);
    expect(first.value.outstandingInvoiceMinor).toBe(60n);
    expect(first.value.outstandingReservedMinor).toBe(55n);

    const second = releasePolicy(
      release({
        releaseMinor: 60n,
        reservation: snapshot({
          programCurrency: 'EUR',
          outstandingInvoiceMinor: 60n,
          outstandingReservedMinor: 55n,
        }),
        scaledRate,
      }),
    );

    expect(second.ok).toBe(true);
    if (second.ok) {
      expect(second.value.deltaMinor).toBe(55n);
      expect(second.value.outstandingInvoiceMinor).toBe(0n);
      expect(second.value.outstandingReservedMinor).toBe(0n);
      expect(second.value.status).toBe('FULLY_RELEASED');
    }

    // The capacity returned across both instalments equals what was reserved.
    expect(first.value.deltaMinor + (second.ok ? second.value.deltaMinor : 0n)).toBe(
      92n,
    );
  });

  it('refuses a release denominated in any currency but the invoice currency', () => {
    const decision = releasePolicy(
      release({
        releaseCurrency: 'EUR',
        reservation: snapshot({ invoiceCurrency: 'USD' }),
      }),
    );

    expect(decision.ok).toBe(false);
    if (!decision.ok) {
      expect(decision.error).toBe('CURRENCY_MISMATCH');
    }
  });

  it('refuses a zero or negative release amount', () => {
    for (const amount of [0n, -1n]) {
      const decision = releasePolicy(release({ releaseMinor: amount }));

      expect(decision.ok).toBe(false);
      if (!decision.ok) {
        expect(decision.error).toBe('INVALID_AMOUNT');
      }
    }
  });

  it.each(['FULLY_RELEASED', 'CANCELLED', 'WRITTEN_OFF'] as const)(
    'refuses a reservation already in terminal status %s',
    (status) => {
      const decision = releasePolicy(
        release({ reservation: snapshot({ status }) }),
      );

      expect(decision.ok).toBe(false);
      if (!decision.ok) {
        expect(decision.error).toBe('RESERVATION_TERMINAL');
      }
    },
  );

  it('does not mutate the input reservation', () => {
    const reservation = snapshot({
      outstandingInvoiceMinor: 1_000n,
      outstandingReservedMinor: 250n,
    });
    const copy = { ...reservation };

    releasePolicy(release({ reservation }));

    expect(reservation).toEqual(copy);
  });
});

