import 'reflect-metadata';
import {
  ArgumentsHost,
  BadRequestException,
  ForbiddenException,
  InternalServerErrorException,
  Logger,
  MethodNotAllowedException,
  NotFoundException,
} from '@nestjs/common';
import { CapacityErrorFilter } from '../../src/capacity/api/error.filter';
import { CapacityRefusal, RefusalCode } from '../../src/capacity/domain/errors';
import { ProgramNotFoundError } from '../../src/capacity/infrastructure/unit-of-work';

interface CapturedResponse {
  status: number | undefined;
  body: Record<string, unknown> | undefined;
}

const invoke = (exception: unknown): CapturedResponse => {
  const captured: CapturedResponse = { status: undefined, body: undefined };
  const response = {
    status(code: number) {
      captured.status = code;
      return response;
    },
    json(body: Record<string, unknown>) {
      captured.body = body;
      return response;
    },
  };
  const host = {
    switchToHttp: () => ({ getResponse: () => response }),
  } as unknown as ArgumentsHost;

  new CapacityErrorFilter().catch(exception, host);
  return captured;
};

const REFUSAL_STATUS: Record<RefusalCode, number> = {
  INSUFFICIENT_CAPACITY: 409,
  PROGRAM_OVER_LIMIT: 409,
  DUPLICATE_INVOICE: 409,
  IDEMPOTENCY_CONFLICT: 409,
  IDEMPOTENCY_EXPIRED: 409,
  REQUEST_IN_FLIGHT: 409,
  FX_RATE_UNAVAILABLE: 409,
  AMOUNT_ROUNDS_TO_ZERO: 409,
  POSITION_UNVERIFIED: 503,
  INVALID_AMOUNT: 400,
  CURRENCY_MISMATCH: 409,
  RESERVATION_TERMINAL: 409,
  RELEASE_EXCEEDS_RESERVED: 409,
  NOT_FOUND: 404,
};

describe('CapacityErrorFilter', () => {
  const codes = Object.keys(REFUSAL_STATUS) as RefusalCode[];

  it.each(codes)('maps %s to its tabled status and code', (code) => {
    const { status, body } = invoke(new CapacityRefusal(code));

    expect(status).toBe(REFUSAL_STATUS[code]);
    expect(body?.code).toBe(code);
    expect(typeof body?.message).toBe('string');
    expect(typeof body?.correlationId).toBe('string');
  });

  it('produces 503 for POSITION_UNVERIFIED, not 409', () => {
    const { status } = invoke(new CapacityRefusal('POSITION_UNVERIFIED'));

    expect(status).toBe(503);
  });

  it('carries refusal details and omits details when there are none', () => {
    const withDetails = invoke(
      new CapacityRefusal('INSUFFICIENT_CAPACITY', {
        requestedMinor: '10',
        availableMinor: '5',
      }),
    );
    expect(withDetails.body?.details).toEqual({
      requestedMinor: '10',
      availableMinor: '5',
    });

    const withoutDetails = invoke(new CapacityRefusal('DUPLICATE_INVOICE'));
    expect(withoutDetails.body).not.toHaveProperty('details');
  });

  it('maps ProgramNotFoundError to 404 NOT_FOUND', () => {
    const { status, body } = invoke(
      new ProgramNotFoundError('b1b2c3d4-0001-4000-8000-000000000011'),
    );

    expect(status).toBe(404);
    expect(body?.code).toBe('NOT_FOUND');
  });

  it('passes a guard-style ForbiddenException through with its own code', () => {
    const { status, body } = invoke(
      new ForbiddenException({
        code: 'INSUFFICIENT_SCOPE',
        message: 'The token lacks a required scope.',
      }),
    );

    expect(status).toBe(403);
    expect(body?.code).toBe('INSUFFICIENT_SCOPE');
    expect(typeof body?.correlationId).toBe('string');
  });

  it('turns a ValidationPipe BadRequestException into 400 VALIDATION_FAILED', () => {
    const { status, body } = invoke(
      new BadRequestException({
        statusCode: 400,
        message: ['invoiceId must be shorter than or equal to 128 characters'],
        error: 'Bad Request',
      }),
    );

    expect(status).toBe(400);
    expect(body?.code).toBe('VALIDATION_FAILED');
    expect(body?.details).toHaveProperty('invoiceId');
  });

  it.each([
    [new NotFoundException(), 404, 'NOT_FOUND'],
    [new ForbiddenException(), 403, 'FORBIDDEN'],
    [new MethodNotAllowedException(), 405, 'METHOD_NOT_ALLOWED'],
  ])(
    'preserves the status of a non-coded HttpException (%#)',
    (exception, status, code) => {
      const captured = invoke(exception);

      expect(captured.status).toBe(status);
      expect(captured.body?.code).toBe(code);
      expect(typeof captured.body?.message).toBe('string');
      expect(typeof captured.body?.correlationId).toBe('string');
      const serialised = JSON.stringify(captured.body);
      expect(serialised).not.toContain('stack');
      expect(serialised).not.toContain('sql');
      expect(serialised).not.toContain('query');
    },
  );

  it('answers 500 INTERNAL for a raw error and leaks no stack, sql or query', () => {
    const errorSpy = jest
      .spyOn(Logger.prototype, 'error')
      .mockImplementation(() => undefined);

    const { status, body } = invoke(new Error('boom'));

    expect(status).toBe(500);
    expect(body?.code).toBe('INTERNAL');
    const serialised = JSON.stringify(body);
    expect(serialised).not.toContain('stack');
    expect(serialised).not.toContain('sql');
    expect(serialised).not.toContain('query');
    expect(errorSpy).toHaveBeenCalled();

    errorSpy.mockRestore();
  });

  it('keeps a 5xx HttpException on the generic INTERNAL path', () => {
    const errorSpy = jest
      .spyOn(Logger.prototype, 'error')
      .mockImplementation(() => undefined);

    const { status, body } = invoke(
      new InternalServerErrorException('connection string leaked'),
    );

    expect(status).toBe(500);
    expect(body?.code).toBe('INTERNAL');
    expect(JSON.stringify(body)).not.toContain('connection string leaked');
    expect(errorSpy).toHaveBeenCalled();

    errorSpy.mockRestore();
  });
});

test/unit/reserve-policy.spec.ts.source:
import { ProgramPosition } from '../../src/capacity/domain/program';
import { FxRate } from '../../src/capacity/domain/ports/fx-rate.provider';
import {
  FxResolution,
  decideReservation,
} from '../../src/capacity/domain/policies/reserve.policy';
import { scaleRate } from '../../src/shared/money';

function program(overrides: Partial<ProgramPosition> = {}): ProgramPosition {
  return {
    id: 'program-1',
    currency: 'USD',
    creditLimitMinor: 1_000_000n,
    localReservedMinor: 0n,
    treasuryReservedMinor: 0n,
    nextSequence: 1n,
    overLimitSince: null,
    investigationRequired: false,
    positionVerified: true,
    ...overrides,
  };
}

function rate(scaled: bigint, value: string): FxRate {
  return {
    scaledRate: scaled,
    rate: value,
    effectiveAt: new Date(0),
    source: 'test',
  };
}

describe('decideReservation', () => {
  it('refuses an unverified program even with ample capacity', () => {
    const decision = decideReservation({
      program: program({ positionVerified: false }),
      invoiceAmountMinor: 100n,
      fx: { kind: 'sameCurrency' },
    });

    expect(decision.kind).toBe('refused');
    if (decision.kind === 'refused') {
      expect(decision.code).toBe('POSITION_UNVERIFIED');
    }
  });

  it('lets POSITION_UNVERIFIED win over PROGRAM_OVER_LIMIT', () => {
    const decision = decideReservation({
      program: program({
        positionVerified: false,
        creditLimitMinor: 1_000n,
        localReservedMinor: 1_200n,
      }),
      invoiceAmountMinor: 100n,
      fx: { kind: 'sameCurrency' },
    });

    expect(decision.kind).toBe('refused');
    if (decision.kind === 'refused') {
      expect(decision.code).toBe('POSITION_UNVERIFIED');
    }
  });

  it('refuses a verified over-limit program with nominal room', () => {
    const decision = decideReservation({
      program: program({
        creditLimitMinor: 1_000n,
        localReservedMinor: 1_200n,
      }),
      invoiceAmountMinor: 1n,
      fx: { kind: 'sameCurrency' },
    });

    expect(decision.kind).toBe('refused');
    if (decision.kind === 'refused') {
      expect(decision.code).toBe('PROGRAM_OVER_LIMIT');
    }
  });

  it('refuses when the FX rate is unavailable', () => {
    const decision = decideReservation({
      program: program(),
      invoiceAmountMinor: 100n,
      fx: { kind: 'unavailable' },
    });

    expect(decision.kind).toBe('refused');
    if (decision.kind === 'refused') {
      expect(decision.code).toBe('FX_RATE_UNAVAILABLE');
    }
  });

  it('refuses an amount that rounds to zero', () => {
    const fx: FxResolution = {
      kind: 'rate',
      rate: rate(scaleRate('0.0067'), '0.0067'),
    };

    const decision = decideReservation({
      program: program(),
      invoiceAmountMinor: 1n,
      fx,
    });

    expect(decision.kind).toBe('refused');
    if (decision.kind === 'refused') {
      expect(decision.code).toBe('AMOUNT_ROUNDS_TO_ZERO');
    }
  });

  it('refuses a request one minor unit above available, with details', () => {
    const decision = decideReservation({
      program: program({ creditLimitMinor: 1_000n, localReservedMinor: 0n }),
      invoiceAmountMinor: 1_001n,
      fx: { kind: 'sameCurrency' },
    });

    expect(decision.kind).toBe('refused');
    if (decision.kind === 'refused') {
      expect(decision.code).toBe('INSUFFICIENT_CAPACITY');
      expect(decision.details).toEqual({
        requestedMinor: '1001',
        availableMinor: '1000',
      });
    }
  });

  it('accepts a request exactly equal to available', () => {
    const decision = decideReservation({
      program: program({ creditLimitMinor: 1_000n, localReservedMinor: 0n }),
      invoiceAmountMinor: 1_000n,
      fx: { kind: 'sameCurrency' },
    });

    expect(decision.kind).toBe('accepted');
    if (decision.kind === 'accepted') {
      expect(decision.reservedMinor).toBe(1_000n);
      expect(decision.fx).toBeNull();
    }
  });

  it('converts a cross-currency amount and returns the same FxRate object', () => {
    const fx: FxResolution = {
      kind: 'rate',
      rate: rate(scaleRate('1.0850000000'), '1.0850000000'),
    };

    const decision = decideReservation({
      program: program({ creditLimitMinor: 10_000_000_00n }),
      invoiceAmountMinor: 1_000_000_00n,
      fx,
    });

    expect(decision.kind).toBe('accepted');
    if (decision.kind === 'accepted') {
      expect(decision.reservedMinor).toBe(108_500_000n);
      expect(decision.fx).toBe(fx.rate);
    }
  });

  it('does not mutate the input program', () => {
    const input = program({ creditLimitMinor: 1_000n, localReservedMinor: 100n });
    const copy = { ...input };

    decideReservation({
      program: input,
      invoiceAmountMinor: 100n,
      fx: { kind: 'sameCurrency' },
    });

    expect(input).toEqual(copy);
  });
});

