import { ProgramEntity } from '../../src/capacity/infrastructure/entities/program.entity';
import { toAvailabilityBody } from '../../src/capacity/application/availability.projection';
import { minorUnitDigits } from '../../src/shared/money';

function program(overrides: Partial<ProgramEntity> = {}): ProgramEntity {
  return Object.assign(new ProgramEntity(), {
    id: 'b1b2c3d4-0001-0000-0000-000000000011',
    organisationId: 'a1b2c3d4-0001-0000-0000-000000000001',
    currency: 'USD',
    creditLimitMinor: 10_000_000_00n,
    localReservedMinor: 1_000_00n,
    treasuryReservedMinor: 2_000_00n,
    nextSequence: 0n,
    overLimitSince: null,
    treasuryVersion: 0n,
    treasuryEffectiveAt: null,
    treasuryAppliedEffectiveAt: null,
    positionChangedAt: new Date('2026-01-01T00:00:00.000Z'),
    investigationRequired: false,
    positionVerified: true,
    ...overrides,
  });
}

describe('toAvailabilityBody', () => {
  it('renders limit, reserved components and signed available as minor-unit strings', () => {
    const body = toAvailabilityBody(program(), false, null);

    expect(body.creditLimit.amountMinor).toBe('1000000000');
    expect(body.reserved.local.amountMinor).toBe('100000');
    expect(body.reserved.treasury.amountMinor).toBe('200000');
    expect(body.reserved.total.amountMinor).toBe('300000');
    expect(body.available.amountMinor).toBe('999700000');
  });

  it('renders a negative available and an active over-limit state', () => {
    const since = new Date('2026-01-01T00:00:00.000Z');
    const body = toAvailabilityBody(
      program({
        creditLimitMinor: 100_000n,
        localReservedMinor: 80_000n,
        treasuryReservedMinor: 80_000n,
        overLimitSince: since,
      }),
      false,
      null,
    );

    expect(body.available.amountMinor).toBe('-60000');
    expect(body.overLimit.active).toBe(true);
    expect(body.overLimit.since).toBe(since.toISOString());
  });

  it('reports null when the process has observed no message for the program', () => {
    const applied = new Date('2026-01-01T00:00:30.000Z');
    const body = toAvailabilityBody(
      program({ treasuryAppliedEffectiveAt: applied }),
      false,
      null,
    );

    expect(body.treasury.lagSeconds).toBeNull();
  });

  it('reports null when no treasury message has been applied', () => {
    const body = toAvailabilityBody(
      program({ treasuryAppliedEffectiveAt: null }),
      false,
      Date.parse('2026-01-01T00:00:30.000Z'),
    );

    expect(body.treasury.lagSeconds).toBeNull();
  });

  it('reports the whole seconds between the applied effective time and the observed head', () => {
    const applied = new Date('2026-01-01T00:00:00.000Z');
    const body = toAvailabilityBody(
      program({ treasuryAppliedEffectiveAt: applied }),
      false,
      applied.getTime() + 65_000,
    );

    expect(body.treasury.lagSeconds).toBe(65);
  });

  it('floors a partial second', () => {
    const applied = new Date('2026-01-01T00:00:00.000Z');
    const body = toAvailabilityBody(
      program({ treasuryAppliedEffectiveAt: applied }),
      false,
      applied.getTime() + 1_900,
    );

    expect(body.treasury.lagSeconds).toBe(1);
  });

  it('reports zero when the applied effective time is at or ahead of the observed head', () => {
    const applied = new Date('2026-01-01T00:00:00.000Z');
    const body = toAvailabilityBody(
      program({ treasuryAppliedEffectiveAt: applied }),
      false,
      applied.getTime() - 5_000,
    );

    expect(body.treasury.lagSeconds).toBe(0);
  });

  it('carries the reconciliation flag it is given', () => {
    expect(toAvailabilityBody(program(), true, null).reconciliationPending).toBe(
      true,
    );
    expect(toAvailabilityBody(program(), false, null).reconciliationPending).toBe(
      false,
    );
  });

  it('produces every field the Availability schema marks required', () => {
    const body = toAvailabilityBody(program(), false, null) as unknown as Record<
      string,
      unknown
    >;

    for (const key of [
      'programId',
      'currency',
      'creditLimit',
      'reserved',
      'available',
      'overLimit',
      'positionChangedAt',
      'treasury',
      'positionVerified',
      'investigationRequired',
    ]) {
      expect(body).toHaveProperty(key);
    }
  });
});

describe('minorUnitDigits', () => {
  it('classifies zero, three and two decimal currencies', () => {
    expect(minorUnitDigits('JPY')).toBe(0);
    expect(minorUnitDigits('KWD')).toBe(3);
    expect(minorUnitDigits('USD')).toBe(2);
  });
});

test/unit/failure-classifier.spec.ts.source:
import {
  PermanentTreasuryError,
  RetryExhaustedError,
  classifyFailure,
  isTransientFailure,
  withRetry,
} from '../../src/treasury/retry/failure-classifier';

describe('classifyFailure', () => {
  it('classifies a PermanentTreasuryError as permanent', () => {
    expect(classifyFailure(new PermanentTreasuryError('nope'))).toBe('PERMANENT');
  });

  it('classifies a Postgres SQLSTATE transient code as transient', () => {
    expect(classifyFailure(Object.assign(new Error('lock'), { code: '55P03' }))).toBe(
      'TRANSIENT',
    );
  });

  it('classifies a network code as transient', () => {
    expect(classifyFailure(Object.assign(new Error('x'), { code: 'ECONNRESET' }))).toBe(
      'TRANSIENT',
    );
  });

  it('reads the code from a wrapped cause', () => {
    expect(
      classifyFailure(new Error('wrap', { cause: Object.assign(new Error('inner'), { code: '40001' }) })),
    ).toBe('TRANSIENT');
  });

  it('classifies an unknown error shape as transient, never permanent', () => {
    expect(classifyFailure(new Error('mystery'))).toBe('TRANSIENT');
    expect(classifyFailure('a plain string')).toBe('TRANSIENT');
    expect(classifyFailure(null)).toBe('TRANSIENT');
    expect(classifyFailure({ code: 42 })).toBe('TRANSIENT');
  });
});

describe('isTransientFailure', () => {
  it('is false for a code-less ordinary error', () => {
    expect(isTransientFailure(new Error('no code here'))).toBe(false);
  });

  it('reads a SQLSTATE code off a TypeORM QueryFailedError-style driverError', () => {
    const driverError = Object.assign(new Error('too many connections'), {
      code: '53300',
    });
    expect(isTransientFailure(Object.assign(new Error('query failed'), { driverError }))).toBe(
      true,
    );
  });

  it('treats a code-less pg-pool connect timeout as transient by message', () => {
    expect(isTransientFailure(new Error('timeout exceeded when trying to connect'))).toBe(
      true,
    );
  });

  it('treats a code-less pg dropped-connection error as transient by message', () => {
    expect(
      isTransientFailure(new Error('Connection terminated unexpectedly')),
    ).toBe(true);
    expect(
      isTransientFailure(
        new Error('Client has encountered a connection error and is not queryable'),
      ),
    ).toBe(true);
  });

  it('covers the whole transient SQLSTATE classes by prefix', () => {
    // 08 connection failure, 53 too many connections, 55 lock not available,
    // 57 admin shutdown, 58 system error.
    for (const code of ['08001', '53400', '55P04', '57P01', '58030']) {
      expect(isTransientFailure(Object.assign(new Error('x'), { code }))).toBe(true);
    }
  });

  it('does not treat a non-contention transaction-rollback code as transient', () => {
    expect(isTransientFailure(Object.assign(new Error('x'), { code: '40002' }))).toBe(
      false,
    );
  });
});

describe('withRetry', () => {
  it('returns immediately on success', async () => {
    const fn = jest.fn().mockResolvedValue('ok');
    await expect(
      withRetry(fn, { maxAttempts: 3, baseDelayMs: 1, maxDelayMs: 2 }),
    ).resolves.toBe('ok');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('rethrows a permanent error after one attempt', async () => {
    const fn = jest.fn().mockRejectedValue(new PermanentTreasuryError('boom'));
    await expect(
      withRetry(fn, { maxAttempts: 5, baseDelayMs: 1, maxDelayMs: 2 }),
    ).rejects.toBeInstanceOf(PermanentTreasuryError);
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('retries a transient error in place and then succeeds', async () => {
    const lockTimeout = () => Object.assign(new Error('lock'), { code: '55P03' });
    let calls = 0;
    const onRetry = jest.fn();
    const fn = jest.fn(async () => {
      calls += 1;
      if (calls < 3) {
        throw lockTimeout();
      }
      return 'done';
    });

    await expect(
      withRetry(fn, { maxAttempts: 3, baseDelayMs: 1, maxDelayMs: 2 }, onRetry),
    ).resolves.toBe('done');
    expect(fn).toHaveBeenCalledTimes(3);
    expect(onRetry).toHaveBeenCalledTimes(2);
  });

  it('throws RetryExhaustedError once maxAttempts is reached', async () => {
    const fn = jest.fn().mockRejectedValue(
      Object.assign(new Error('lock'), { code: '55P03' }),
    );

    await expect(
      withRetry(fn, { maxAttempts: 2, baseDelayMs: 1, maxDelayMs: 1 }),
    ).rejects.toBeInstanceOf(RetryExhaustedError);
    expect(fn).toHaveBeenCalledTimes(2);
  });
});

test/unit/money.spec.ts.source:
import {
  CurrencyMismatchError,
  add,
  compare,
  currency,
  fromDecimalString,
  isZero,
  money,
  negate,
  subtract,
  toDecimalString,
} from '../../src/shared/money/money';

describe('money', () => {
  it('rejects construction from number', () => {
    expect(() => money(100 as unknown as bigint, 'USD')).toThrow(TypeError);
  });

  it('rejects malformed currency codes', () => {
    expect(() => currency('usd')).toThrow();
    expect(() => currency('US')).toThrow();
    expect(() => currency('USDD')).toThrow();
    expect(() => currency('US1')).toThrow();
  });

  it('rejects arithmetic across currencies', () => {
    expect(() => add(money(1n, 'USD'), money(1n, 'EUR'))).toThrow(
      CurrencyMismatchError,
    );
  });

  it('round trips one above Number.MAX_SAFE_INTEGER', () => {
    const m = money(9007199254740993n, 'USD');
    expect(fromDecimalString(toDecimalString(m, 2), 'USD', 2)).toEqual(m);
  });

  it('renders negative minor units', () => {
    expect(toDecimalString(money(-1n, 'USD'), 2)).toBe('-0.01');
  });

  it('renders zero minor units', () => {
    expect(toDecimalString(money(0n, 'USD'), 2)).toBe('0.00');
  });

  it('rejects excess fractional digits on parse', () => {
    expect(() => fromDecimalString('1.234', 'USD', 2)).toThrow(TypeError);
  });

  it('returns a new object without mutating operands', () => {
    const a = money(100n, 'USD');
    const b = money(250n, 'USD');
    const aCopy = { ...a };
    const bCopy = { ...b };

    const result = add(a, b);

    expect(result).not.toBe(a);
    expect(result).not.toBe(b);
    expect(result.minor).toBe(350n);
    expect(a).toEqual(aCopy);
    expect(b).toEqual(bCopy);
  });
});

describe('money arithmetic and ordering', () => {
  it('subtracts same-currency amounts and rejects a mismatch', () => {
    expect(subtract(money(250n, 'USD'), money(100n, 'USD'))).toEqual(
      money(150n, 'USD'),
    );
    expect(() => subtract(money(1n, 'USD'), money(1n, 'EUR'))).toThrow(
      CurrencyMismatchError,
    );
  });

  it('negates without mutating its argument', () => {
    const a = money(100n, 'USD');
    expect(negate(a)).toEqual(money(-100n, 'USD'));
    expect(a).toEqual(money(100n, 'USD'));
  });

  it('detects zero', () => {
    expect(isZero(money(0n, 'USD'))).toBe(true);
    expect(isZero(money(1n, 'USD'))).toBe(false);
  });

  it('orders same-currency amounts and rejects a mismatch', () => {
    expect(compare(money(1n, 'USD'), money(2n, 'USD'))).toBe(-1);
    expect(compare(money(2n, 'USD'), money(1n, 'USD'))).toBe(1);
    expect(compare(money(2n, 'USD'), money(2n, 'USD'))).toBe(0);
    expect(() => compare(money(1n, 'USD'), money(1n, 'EUR'))).toThrow(
      CurrencyMismatchError,
    );
  });

  it('renders whole-unit currencies without a decimal point', () => {
    expect(toDecimalString(money(1234n, 'JPY'), 0)).toBe('1234');
    expect(toDecimalString(money(-1n, 'JPY'), 0)).toBe('-1');
  });

  it('rejects malformed and over-precise decimal strings', () => {
    expect(() => fromDecimalString('not-a-number', 'USD', 2)).toThrow(TypeError);
    expect(() => fromDecimalString('12345678901234567890', 'USD', 2)).toThrow(
      TypeError,
    );
    expect(() => fromDecimalString('1234567890123456789.0', 'USD', 2)).toThrow(
      TypeError,
    );
    expect(() => fromDecimalString('1.2.3', 'USD', 2)).toThrow(TypeError);
  });

  it('parses a negative decimal string back to negative minor units', () => {
    expect(fromDecimalString('-0.01', 'USD', 2)).toEqual(money(-1n, 'USD'));
  });
});

test/unit/reconciliation-check.spec.ts.source:
import { DataSource } from 'typeorm';
import { ReconciliationCheckService } from '../../src/capacity/application/reconciliation-check.service';
import {
  investigationRequiredPrograms,
  resetMetrics,
} from '../../src/observability/metrics';

const POSITION_COLUMN_ASSIGNMENT =
  /(local_reserved_minor|treasury_reserved_minor|credit_limit_minor|next_sequence|over_limit_since|treasury_version|treasury_effective_at|position_changed_at)\s*=/i;

function serviceWith(query: jest.Mock): ReconciliationCheckService {
  return new ReconciliationCheckService({ query } as unknown as DataSource);
}

function executedSql(query: jest.Mock): string[] {
  return query.mock.calls.map((call) => String(call[0]));
}

describe('ReconciliationCheckService', () => {
  beforeEach(() => {
    resetMetrics();
  });

  it('flags a mismatched program and writes no position column', async () => {
    const query = jest
      .fn()
      .mockResolvedValueOnce([
        {
          program_id: '00000000-0000-4000-8000-000000000001',
          local_reserved_minor: '1000',
          active_outstanding: '900',
        },
      ])
      .mockResolvedValue([]);
    const service = serviceWith(query);

    const report = await service.check();

    expect(report.programsChecked).toBe(1);
    expect(report.mismatches).toHaveLength(1);
    expect(report.mismatches[0]?.programId).toBe(
      '00000000-0000-4000-8000-000000000001',
    );
    expect(report.mismatches[0]?.expected).toBe(900n);
    expect(report.mismatches[0]?.actual).toBe(1000n);

    const sql = executedSql(query);
    expect(
      sql.some((statement) =>
        /UPDATE program[\s\S]*investigation_required\s*=\s*TRUE/i.test(
          statement,
        ),
      ),
    ).toBe(true);
    for (const statement of sql) {
      expect(statement).not.toMatch(POSITION_COLUMN_ASSIGNMENT);
    }

    const metric = await investigationRequiredPrograms.get();
    expect(metric.values[0]?.value).toBe(1);
  });

  it('writes nothing and reports zero when every program reconciles', async () => {
    const query = jest.fn().mockResolvedValue([
      {
        program_id: '00000000-0000-4000-8000-000000000002',
        local_reserved_minor: '500',
        active_outstanding: '500',
      },
    ]);
    const service = serviceWith(query);

    const report = await service.check();

    expect(report.programsChecked).toBe(1);
    expect(report.mismatches).toEqual([]);
    expect(executedSql(query).some((sql) => /UPDATE/i.test(sql))).toBe(false);

    const metric = await investigationRequiredPrograms.get();
    expect(metric.values[0]?.value).toBe(0);
  });
});

test/unit/cancel-policy.spec.ts.source:
import { cancelPolicy } from '../../src/capacity/domain/policies/cancel.policy';
import {
  ReservationSnapshot,
  ReservationStatus,
} from '../../src/capacity/domain/policies/release.policy';

function snapshot(
  overrides: Partial<ReservationSnapshot> = {},
): ReservationSnapshot {
  return {
    invoiceCurrency: 'EUR',
    programCurrency: 'USD',
    outstandingInvoiceMinor: 33_333n,
    outstandingReservedMinor: 36_166n,
    status: 'ACTIVE',
    ...overrides,
  };
}

describe('cancelPolicy', () => {
  it('cancels an ACTIVE reservation with cause CANCELLATION and returns the whole reserved remainder', () => {
    const decision = cancelPolicy(snapshot({ status: 'ACTIVE' }));

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor).toBe(36_166n);
      expect(decision.value.cause).toBe('CANCELLATION');
      expect(decision.value.status).toBe('CANCELLED');
    }
  });

  it('writes off a PARTIALLY_RELEASED reservation, returning only what remains reserved', () => {
    const decision = cancelPolicy(
      snapshot({
        status: 'PARTIALLY_RELEASED',
        outstandingInvoiceMinor: 13_333n,
        outstandingReservedMinor: 14_466n,
      }),
    );

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor).toBe(14_466n);
      expect(decision.value.cause).toBe('WRITE_OFF');
      expect(decision.value.status).toBe('WRITTEN_OFF');
    }
  });

  it('states the returned capacity as a positive magnitude for the service to negate', () => {
    const decision = cancelPolicy(snapshot());

    expect(decision.ok).toBe(true);
    if (decision.ok) {
      expect(decision.value.deltaMinor > 0n).toBe(true);
    }
  });

  it.each(['FULLY_RELEASED', 'CANCELLED', 'WRITTEN_OFF'] as const)(
    'refuses a reservation already in terminal status %s',
    (status: ReservationStatus) => {
      const decision = cancelPolicy(snapshot({ status }));

      expect(decision.ok).toBe(false);
      if (!decision.ok) {
        expect(decision.error).toBe('RESERVATION_TERMINAL');
      }
    },
  );

  it('does not mutate the input reservation', () => {
    const reservation = snapshot({ status: 'PARTIALLY_RELEASED' });
    const copy = { ...reservation };

    cancelPolicy(reservation);

    expect(reservation).toEqual(copy);
  });
});

test/unit/rounding.spec.ts.source:
import { money } from '../../src/shared/money/money';
import { convert, roundHalfUp, scaleRate } from '../../src/shared/money/convert';

describe('roundHalfUp', () => {
  it('rounds halves away from zero for both signs', () => {
    expect(roundHalfUp(5n, 10n)).toBe(1n);
    expect(roundHalfUp(-5n, 10n)).toBe(-1n);
  });

  it('rounds below and above the half point', () => {
    expect(roundHalfUp(4n, 10n)).toBe(0n);
    expect(roundHalfUp(15n, 10n)).toBe(2n);
  });
});

describe('scaleRate', () => {
  it('scales decimal rates with ten fractional digits', () => {
    expect(scaleRate('1.0850000000')).toBe(10850000000n);
    expect(scaleRate('1.085')).toBe(10850000000n);
  });

  it('rejects a zero rate', () => {
    expect(() => scaleRate('0')).toThrow();
  });

  it('rejects more than ten fractional digits', () => {
    expect(() => scaleRate('1.08500000001')).toThrow();
  });
});

describe('convert', () => {
  it('reports a non-zero amount that rounds to zero', () => {
    expect(convert(money(1n, 'JPY'), 'USD', scaleRate('0.0067'))).toEqual({
      kind: 'roundsToZero',
    });
  });

  it('converts a genuine zero to zero', () => {
    const result = convert(money(0n, 'JPY'), 'USD', scaleRate('0.0067'));
    expect(result.kind).toBe('converted');
    if (result.kind === 'converted') {
      expect(result.amount.minor).toBe(0n);
      expect(result.amount.currency).toBe('USD');
    }
  });

  it('converts an amount at the scaled rate', () => {
    const result = convert(
      money(1_000_000_00n, 'EUR'),
      'USD',
      scaleRate('1.0850000000'),
    );
    expect(result.kind).toBe('converted');
    if (result.kind === 'converted') {
      expect(result.amount.minor).toBe(108500000n);
    }
  });
});

test/unit/result.spec.ts.source:
import {
  err,
  isErr,
  isOk,
  map,
  mapErr,
  ok,
  unwrapOr,
} from '../../src/shared/result';

describe('result', () => {
  it('isOk(ok(1)) is true, isErr(ok(1)) is false, and the mirror', () => {
    expect(isOk(ok(1))).toBe(true);
    expect(isErr(ok(1))).toBe(false);
    expect(isErr(err('boom'))).toBe(true);
    expect(isOk(err('boom'))).toBe(false);
  });

  it('map applies to Ok and passes Err through untouched', () => {
    expect(map(ok(1), (n) => n + 1)).toEqual(ok(2));

    const failure = err<string>('boom');
    expect(map(failure, (n: number) => n + 1)).toBe(failure);
  });

  it('mapErr applies to Err and passes Ok through untouched', () => {
    expect(mapErr(err('boom'), (e) => e.toUpperCase())).toEqual(err('BOOM'));

    const success = ok(1);
    expect(mapErr(success, (e: string) => e.toUpperCase())).toBe(success);
  });

  it('ok(1) is frozen: assigning .value throws in strict mode', () => {
    const result = ok(1);
    expect(Object.isFrozen(result)).toBe(true);
    expect(() => {
      (result as unknown as { value: number }).value = 2;
    }).toThrow(TypeError);
  });

  it('unwrapOr returns the value for Ok and the fallback for Err', () => {
    expect(unwrapOr(ok(1), 0)).toBe(1);
    expect(unwrapOr(err('boom'), 0)).toBe(0);
  });
});

test/unit/apply-snapshot-guard.spec.ts.source:
import { ConfigService } from '@nestjs/config';
import { ApplySnapshotService } from '../../src/capacity/application/apply-snapshot.service';

interface GuardAccess {
  exceedsMagnitudeGuard(
    deltaTreasury: bigint,
    creditLimitMinor: bigint,
  ): boolean;
}

function serviceWithRatio(ratio: number): GuardAccess {
  const config = {
    get: (key: string): unknown =>
      key === 'SNAPSHOT_DELTA_GUARD_RATIO' ? ratio : undefined,
  } as unknown as ConfigService;

  const service = new ApplySnapshotService(
    {} as never,
    {} as never,
    {} as never,
    {} as never,
    config,
  );

  return service as unknown as GuardAccess;
}

describe('ApplySnapshotService.exceedsMagnitudeGuard', () => {
  it('quarantines a treasury delta above the guard ratio', () => {
    expect(serviceWithRatio(0.5).exceedsMagnitudeGuard(501n, 1000n)).toBe(true);
  });

  it('admits a treasury delta exactly at the guard ratio', () => {
    expect(serviceWithRatio(0.5).exceedsMagnitudeGuard(500n, 1000n)).toBe(
      false,
    );
  });

  it('is exact for a credit limit above 2^53', () => {
    expect(
      serviceWithRatio(0.5).exceedsMagnitudeGuard(
        4_503_599_627_370_497n,
        9_007_199_254_740_993n,
      ),
    ).toBe(true);
  });
});

test/unit/refusal-status.spec.ts.source:
import { REFUSAL_STATUS } from '../../src/capacity/api/error.filter';
import { REFUSAL_CODES } from '../../src/capacity/domain/errors';

describe('refusal status contract', () => {
  it('has no duplicate refusal codes', () => {
    expect(new Set(REFUSAL_CODES).size).toBe(REFUSAL_CODES.length);
  });

  it('agrees with the status map on the exact set of codes', () => {
    const statusCodes = Object.keys(REFUSAL_STATUS).sort();
    const refusalCodes = [...REFUSAL_CODES].sort();

    expect(statusCodes).toEqual(refusalCodes);
    expect(new Set(statusCodes)).toEqual(new Set(refusalCodes));
  });

  it('maps POSITION_UNVERIFIED to 503', () => {
    expect(REFUSAL_STATUS.POSITION_UNVERIFIED).toBe(503);
  });

  it('maps NOT_FOUND to 404', () => {
    expect(REFUSAL_STATUS.NOT_FOUND).toBe(404);
  });

  it('maps INVALID_AMOUNT to 400', () => {
    expect(REFUSAL_STATUS.INVALID_AMOUNT).toBe(400);
  });

  it('maps every refusal to an integer between 400 and 599', () => {
    for (const status of Object.values(REFUSAL_STATUS)) {
      expect(Number.isInteger(status)).toBe(true);
      expect(status).toBeGreaterThanOrEqual(400);
      expect(status).toBeLessThanOrEqual(599);
    }
  });
});

